"""Generate accessible static executive summaries from measured evidence."""
from pathlib import Path
import html
import json
ROOT = Path(__file__).resolve().parents[1]
esc = html.escape

def shell(title, body):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · GEMS research</title><link rel="stylesheet" href="style.css"></head><body><header><a class="brand" href="index.html">GEMS <span>/ KARAGE 01</span></a><nav><a href="index.html">Overview</a><a href="executive-summary.html">Submission guide</a><a href="https://github.com/karagemop466-tech/GEMSDOEkarage1/blob/main/knowledge/REVIEW.md">Research</a></nav></header><main>{body}</main><footer>Evidence first. No automatic competition submissions. <a href="docs/data/run_card.json">Machine-readable run card ↗</a></footer></body></html>'''


def main():
    import runpy
    runpy.run_path(str(ROOT / 'scripts/build_current_review.py'), run_name='__main__')
    return
    # Preserve the concurrently merged detailed site and its independent audit.
    from build_detail_pages import main as build_details
    build_details()
    data = json.loads((ROOT/'docs/data/sources.json').read_text())
    audit = json.loads((ROOT/'docs/data/raster_audit.json').read_text())
    bysite = {r['site']: r for r in audit['rasters']}
    rows, cards = [], []
    for s in data['sites']:
        r = bysite[s['site']]
        maximum = max(c['within_3px_fraction'] for c in r['comparisons'])
        exact = [c['site'] for c in r['comparisons'] if c['same_dot_mask']]
        rows.append(f'''<tr><th><a href="#{s['site']}">{s['site']}</a></th><td><a href="{esc(s['artifact_url'])}">{esc(s['artifact'])}</a><small>Historical research file — not a new submission</small></td><td>Not estimable<small>No artifact-linked organizer receipt</small></td><td><span class="bad">FAIL</span><small>{maximum:.1%} max 3-px overlap</small></td><td>No</td></tr>''')
        cards.append(f'''<article id="{s['site']}"><div class="eyebrow">SITE EXECUTIVE SUMMARY</div><h3>{s['site']}</h3><p><strong>Submit: no.</strong> This is the historical best identified in the owner's supplied ranking, not a verified current winner. No new submission is recommended.</p><p>{r['dots']:,} positive pixels. {'Exactly the same positive-pixel mask as '+', '.join(exact)+'.' if exact else 'No exact mask match among the other eight audited files.'} It nevertheless fails the literal proximity rule: maximum directional overlap is {maximum:.2%}.</p><p>Leaderboard estimate: <strong>not estimable</strong>. Surface uniqueness, leakage and comparable holdout improvement are not certified by this historical audit.</p><details><summary>Artifact identity &amp; evidence</summary><p><a href="{esc(s['source_url'])}">Pinned source README ↗</a></p><p class="mono">{s['artifact_sha256']}</p><p>Grid: {esc(r['crs'])}; {r['shape'][0]} × {r['shape'][1]}. {'Whole-array finite.' if r['all_finite'] else 'Contains NaN: not cleared by our strict upload validator.'} Comparison domain is peer-derived, not an authenticated submission template.</p></details></article>''')
    body = f'''<div class="eyebrow">FAULT-MAPPING RESEARCH / EVIDENCE REVIEW</div><h1>A clear decision.<br>Before the next submission.</h1><p class="lead">Nine historical candidates audited. No new file cleared for competition. Scientific novelty and format validity are separate gates.</p><section class="decision"><span class="badge">DO NOT SUBMIT</span><h2>No competition-ready TIFF</h2><p>The method lane and designated template are missing. Creating a renamed copy or arbitrary new raster would violate the protocol. No holdout result or leaderboard estimate is invented.</p><a class="button" href="executive-summary.html">See submission gates →</a></section><div class="stats"><div><strong>9 / 9</strong><span>historical masks fail overlap</span></div><div><strong>0</strong><span>training experiments / slots used</span></div><div><strong>Unavailable</strong><span>defensible score estimate</span></div></div><section><div class="eyebrow">EXECUTIVE COMPARISON</div><h2>What to download — and what not to submit</h2><p>Links below open pinned historical artifacts for research only. They are not new submission downloads. Counts and overlap percentages are audit measurements, not performance scores.</p><p class="muted">Source check: {esc(data['checked_at'])}. Scope: nine historical files, not a complete live registry.</p><div class="table-wrap"><table><thead><tr><th>Site</th><th>Historical file / source</th><th>Estimated leaderboard score</th><th>Unique under protocol?</th><th>Submit?</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div></section><section><h2>What the H33-B2 result actually tells us</h2><p>H33-B2 is the highest result in the supplied nine-site historical ranking. Without an artifact-linked organizer receipt, that ranking is not organizer-confirmed evidence. Our independent raster audit establishes strong family similarity, not the causal explanation for the reported performance.</p><p>Thinning redundant predictions can retain distance-tolerant coverage while reducing false-positive mass. That is a testable explanation, not a validated forecast. Reproducing its dots is not a distinct scientific strategy.</p><a href="https://github.com/karagemop466-tech/GEMSDOEkarage1/blob/main/knowledge/REVIEW.md">Read hypotheses, confounders and next steps ↗</a></section><div class="site-grid">{''.join(cards)}</div><section><h2>Evidence you can audit</h2><ul><li><a href="docs/data/sources.json">Source refs, artifact names and SHA-256 hashes</a></li><li><a href="docs/data/raster_audit.json">Independent pairwise comparisons</a></li><li><a href="docs/data/run_card.json">Negative run card and missing evidence</a></li><li><a href="https://github.com/drivendataorg/gems-prize-reference-solution">Official organizer reference implementation</a></li><li><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard — not verified live here</a></li></ul></section>'''
    # Keep the first integrated dashboard as a reproducible legacy view.
    # The current homepage is maintained by render_site.py.
    (ROOT/'legacy-overview.html').write_text(shell('Executive overview', body))
    guide = '''<div class="eyebrow">SUBMISSION GUIDE</div><h1>One file.<br>All gates passed.</h1><section class="decision"><span class="badge">CURRENTLY BLOCKED</span><h2>No new TIFF is available to submit</h2><p>The checks are designed to fail closed automatically. A missing result is not a request for a human inspector to guess whether a file is good enough.</p></section><section><h2>The required sequence</h2><ol><li><strong>Method and data.</strong> Identify the assigned parallel lane and shared template; restore pinned features, official grid, footprint and whole fault segments.</li><li><strong>Leakage control.</strong> Withhold whole segments with a buffer. Derive catalogue features from visible faults only. Run single-feature canaries; investigate any AUC above 0.90.</li><li><strong>Surface uniqueness.</strong> Compare against the complete registry before placing dots. Stop if rank-correlation exceeds 0.90 or the specified proximity rule fails.</li><li><strong>Holdout improvement.</strong> Use the shared pooled-DTI evaluator, alpha 0.2, beta 0.8, 300 m triangular kernel. Record evaluator version, withheld positives and 95% CI; compare to the same-fold current best.</li><li><strong>Final uniqueness.</strong> Stop if more than 70% of candidate dots fall within 3 px of any registry mask. Different SHA hashes do not prove different predictions.</li><li><strong>Saved-byte validation.</strong> Use the shared writer. Reopen the TIFF and require one band, finite [0,1] values and exact template CRS, shape and transform. Our conservative validator also rejects NaN outside the footprint.</li><li><strong>Separate selector.</strong> Only after all evidence passes, check the actual weekly allowance and authorize a slot. This project does not auto-submit.</li></ol></section><section><h2>When a candidate is cleared</h2><p>A future release must show a unique filename, SHA-256, download link, validation report, holdout evidence and a note of at most 140 characters. Download the .tif (not this HTML page or a JSON report), choose it in the official submission form, paste the note, and retain the receipt linked to the file hash. A ZIP must contain exactly one TIFF.</p><p>These are instructions for a future cleared artifact, not authorization to upload any historical file linked here.</p></section><section><h2>About “Predicted values must be in range [0,1]”</h2><p>Potential causes include negative nodata sentinels, infinity, NaN handling or predictions outside the interval. The original failed file was not supplied, so its cause cannot be diagnosed. Do not blindly clip bad inputs: first inspect prediction generation, footprint and nodata handling, then validate the saved bytes. Format success alone does not prove portal acceptance or competitive performance.</p><pre>python scripts/validate_artifact.py candidate.tif official_template.tif binary_footprint.tif</pre></section><section><h2>Access limitations</h2><p>The shell can fetch GitHub evidence and Python packages; direct data hosts such as Dropbox are outside its network allowlist. Public official pages were reviewed through web retrieval; login-walled data and submission pages remain inaccessible. GitHub mirrors do not authenticate organizer provenance. No current weekly allowance, login state or file-bound organizer receipt has been verified here.</p></section>'''
    (ROOT/'executive-summary.html').write_text(shell('Submission guide', guide))

if __name__ == '__main__':
    main()
